from bisect import bisect_left
for _ in range(int(input())):
	(n, q) = map(int, input().split())
	s = input()
	index = []
	for i in range(n - 2):
		dictt = {}
		for j in s[i:i + 3]:
			if j in dictt:
				dictt[j] += 1
			else:
				dictt[j] = 1
		if max(dictt.values()) >= 2:
			index += [i + 1]
	for __ in range(q):
		(l, r) = map(int, input().split())
		ind = bisect_left(index, l)
		if ind == len(index):
			print('NO')
		elif index[ind] + 2 <= r:
			print('YES')
		else:
			print('NO')
